text:
(e) => {
	e.preventDefault();
	this.flyTarget = null;
	// Zoom responsivo e progressivo: amplo alcance [0.3 a 60.0]
	const zoomStep = (e.deltaY > 0 ? 1 : -1) * Math.max(0.08, this.distance * 0.09);
	this.distance = Math.max(0.3, Math.min(60.0, this.distance + zoomStep));
	this.onUpdate?.();
},
